parameters.command:
python3 - << 'PYEOF'
import json

# Load extra defs (script + end)
with open('/tmp/extra-defs.json') as f:
    extra_defs = json.load(f)

# Load current flow
with open('/work/output/artifacts/skill-flow-calculator/Calculator/Calculator/Calculator.flow') as f:
    flow = json.load(f)

# Current definitions has only core.trigger.manual — keep it, append script+end
flow['definitions'].extend(extra_defs)

# Add script node and end node to nodes
flow['nodes'].append({
    "id": "multiply",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {"label": "Multiply Numbers"},
    "inputs": {
        "script": "return { product: $vars.numberA * $vars.numberB };"
    },
    "outputs": {
        "output": {
            "type": "object",
            "description": "The return value of the script",
            "source": "=result.response",
            "var": "output"
        },
        "error": {
            "type": "object",
            "description": "Error information if the script fails",
            "source": "=result.Error",
            "var": "error"
        }
    }
})

flow['nodes'].append({
    "id": "end",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": {"label": "End"},
    "inputs": {},
    "outputs": {
        "product": {
            "source": "=js:$vars.multiply.output.product"
        }
    }
})

# Wire edges
flow['edges'] = [
    {
        "id": "edge-start-multiply",
        "sourceNodeId": "start",
        "sourcePort": "output",
        "targetNodeId": "multiply",
        "targetPort": "input"
    },
    {
        "id": "edge-multiply-end",
        "sourceNodeId": "multiply",
        "sourcePort": "success",
        "targetNodeId": "end",
        "targetPort": "input"
    }
]

# Declare variables: 2 inputs, 1 output
flow['variables'] = {
    "globals": [
        {
            "id": "numberA",
            "direction": "in",
            "type": "number",
            "defaultValue": 0,
            "description": "First number for multiplication"
        },
        {
            "id": "numberB",
            "direction": "in",
            "type": "number",
            "defaultValue": 0,
            "description": "Second number for multiplication"
        },
        {
            "id": "product",
            "direction": "out",
            "type": "number",
            "description": "The product of numberA and numberB"
        }
    ],
    "nodes": [
        {
            "id": "multiply.output",
            "type": "object",
            "description": "Script output containing the product",
            "binding": {"nodeId": "multiply", "outputId": "output"}
        },
        {
            "id": "multiply.error",
            "type": "object",
            "description": "Error if script fails",
            "binding": {"nodeId": "multiply", "outputId": "error"}
        }
    ],
    "variableUpdates": {}
}

# Layout: add placeholder positions for new nodes (format will rewrite)
flow['layout']['nodes']['multiply'] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
flow['layout']['nodes']['end'] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}

with open('/work/output/artifacts/skill-flow-calculator/Calculator/Calculator/Calculator.flow', 'w') as f:
    json.dump(flow, f, indent=2)

print("Written OK")
PYEOF

